      hu: ["Dohánytermesztés", "Orientális dohány", "Mezőgazdaság", "Rodope"],
      ro: ["Cultivarea tutunului", "Tutun oriental", "Agricultură", "Rodopi"],
      en: ["Tobacco cultivation", "Oriental tobacco", "Agriculture", "Rhodopes"],
